/* Linked resources, as generated by `sst dev` / `sst deploy`. Committed so the handlers typecheck in CI. */
import "sst";
declare module "sst" {
  export interface Resource {
    Incoming: { name: string; type: "sst.aws.Bucket" };
    PriceQueue: { type: "sst.aws.Queue"; url: string };
    Prices: { name: string; type: "sst.aws.Dynamo" };
  }
}
export {};
